package com.procurement.purchaseorder.entity;import com.procurement.product.entity.Product;import jakarta.persistence.*;import lombok.*;import java.math.BigDecimal;@Entity@Table(name="purchase_order_lines")@Getter@Setter@NoArgsConstructor@AllArgsConstructor@Builder public class PurchaseOrderLine{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="purchase_order_line_id")private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="purchase_order_id",nullable=false)private PurchaseOrder purchaseOrder;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="product_id",nullable=false)private Product product;@Column(name="quantity_ordered",nullable=false,precision=15,scale=3)private BigDecimal quantityOrdered;@Column(name="quantity_received",nullable=false,precision=15,scale=3)@Builder.Default private BigDecimal quantityReceived=BigDecimal.ZERO;@Column(name="unit_price",nullable=false,precision=15,scale=2)private BigDecimal unitPrice;@Column(name="discount_percentage",nullable=false,precision=5,scale=2)@Builder.Default private BigDecimal discountPercentage=BigDecimal.ZERO;@Column(name="tax_percentage",nullable=false,precision=5,scale=2)@Builder.Default private BigDecimal taxPercentage=BigDecimal.ZERO;@Column(name="line_amount",nullable=false,precision=15,scale=2)private BigDecimal lineAmount;@Column(length=500)private String remarks;}
